"""Sort the given models based on their dependencies. It uses a depth-first search to sort the models based on their dependencies and returns the sorted list of models.

:param models: List. A list of model instances to be sorted.
:return: List. The sorted list of model instances based on their dependencies.
"""
# Create a dictionary to store the dependencies of each model.
dependencies = {}
for model in models:
    dependencies[model] = set()

# Iterate through the models and add the dependencies of each model to the dictionary.
for model in models:
    for field in model._meta.fields:
        if isinstance(field, peewee.ForeignKeyField):
            dependencies[model].add(field.rel_model)

# Perform a depth-first search to sort the models based on their dependencies.
sorted_models = []
visited = set()

def dfs(model):
    if model in visited:
        return
    visited.add(model)
    for dependency in dependencies[model]:
        dfs(dependency)
    sorted_models.append(model)

for model in models:
    dfs(model)

return sorted_models

