    raise TypeError('step must be an int, datetime.timedelta, or tuple')
if isinstance(step, tuple):
    step = datetime.timedelta(*step)
if step.days == 0:
    raise ValueError('step must be a non-zero timedelta')
if step.days < 0:
    start, stop = stop, start
while start <= stop:
    yield start
    start += step
if inclusive and start == stop:
    yield start

