return schema

"""This function returns all undeclared variables in the given AST.

:param ast: nodes.Template. The AST of a Jinja2 template.
:return: Set[str]. A set of all variables in the AST that will be looked up from the context at runtime.
"""
#src/jinja2/meta.py
def _find_undeclared_variables(node: nodes.Node) -> t.Set[str]:
    if isinstance(node, nodes.TemplateData):
        return set()
    elif isinstance(node, nodes.Output):
        return _find_undeclared_variables(node.node)
    elif isinstance(node, nodes.For):
        return _find_undeclared_variables(node.seq) | _find_undeclared_variables(node.target)
    elif isinstance(node, nodes.If):
        return _find_undeclared_variables(node.test) | _find_undeclared_variables(node.body) | _find_undeclared_variables(node.else_)
    elif isinstance(node, nodes.With):
        return _find_undeclared_variables(node.body)
    elif isinstance(node, nodes.CallBlock):
        return _find_undeclared_variables(node.node)
    elif isinstance(node, nodes.Macro):
        return _find_undeclared_variables(node.body)
    elif isinstance(node, nodes.Import):
        return _find_undeclared_variables(node.node)
    elif isinstance(node, nodes.FromImport):
        return _find_undeclared_variables(node.node)
    elif isinstance(node, nodes.Include):
        return _find_undeclared_variables(node.node)
    elif isinstance(node, nodes.AssignBlock):
        return _find_undeclared_variables(node.node)
    elif isinstance(node, nodes.Assign):
        return _find_undeclared_variables(node.node)
    elif isinstance(node, nodes.Getattr):
        return _find_undeclared_variables(node.node)
    elif isinstance(node, nodes.Call):
        return _find_undeclared_variables(node.node)
    elif isinstance(node, nodes.Filter):
        return _find_undeclared_variables(node.node)
    elif isinstance(node, nodes.Test):
        return _find_undeclared_variables(node.node)
    elif isinstance(node, nodes.Unary):
        return _find_undeclared_variables(node.node)
    elif isinstance(node, nodes.Binary):
        return _find_undeclared_variables(node.left) | _find_undeclared_variables(node.right)
    elif isinstance(node, nodes.Getitem):
        return _find_undeclared_variables(node.node) | _find_undeclared_variables(node.slice)
    elif isinstance(node, nodes.Slice):
        return _find_undeclared_variables(node.lower) | _find_undeclared_variables(node.upper) | _find_undeclared_variables(node.step)
    elif isinstance(node, nodes.Name):
        return set()
    elif isinstance(node, nodes.Tuple):
        return set.union(*[_find_undeclared_variables(n) for n in node.nodes])
    elif isinstance(node, nodes.List):
        return set.union(*[_find_undeclared_variables(n) for n in node.nodes])
    elif isinstance(node, nodes._Undefined):
        return set()
    elif isinstance(node, nodes.Dict):
        return set.union(*[_find_undeclared_variables(n) for n in node.items])
    elif isinstance(node, nodes.DictComp):
        return _find_undeclared_variables(node.key) | _find_undeclared_variables(node.value)
    elif isinstance(node, nodes.ListComp):
        return _find_undeclared_variables(node.node)
    elif isinstance(node, nodes.SetComp):
        return _find_undeclared_variables(node.node)
    elif isinstance(node, nodes.GeneratorExp):
        return _find_undeclared_variables(node.node)
    elif isinstance(node, nodes.DictComp):
        return _find_undeclared_variables(node.key) | _find_undeclared-variables(node.value)
    elif isinstance(node, nodes.ListComp):
        return _find_undeclared_variables(node.node) | _find_undeclared_variables(node.ifs)
    elif isinstance(node, nodes.SetComp):
        return _find_undeclared_variables(node.node) | _find_undeclared_variables(node.ifs)
    elif (
        isinstance(node, nodes.Tuple)
        or isinstance(node, nodes.List)
        or isinstance(node, nodes.Dict)
        or isinstance(node, nodes.DictComp)
        or isinstance(node, nodes.ListComp)
        or isinstance(node, nodes.SetComp)
        or isinstance(node, nodes.GeneratorExp)
    ):
        return set.union(*[_find_undeclared_variables(n) for n in node.nodes])
    else:
        raise TypeError(f"Unknown node type: {type(node)}")

return _find_undeclared_variables(ast)

"""Check if any of the queries in the given list is considered destructive. It checks if any of the queries start with certain keywords that are commonly associated with destructive actions.

:param queries: List of strings. The queries to be checked.
:return: Bool. True if any of the queries is considered destructive, False otherwise.
"""
destructive_keywords = ["drop", "delete", "truncate", "alter", "create", "insert", "update", "rename", "set"]
for query in queries:
    for keyword in destructive_keywords:
        if query.lower().startswith(keyword):
            return True
return False

"""This function takes a callable object and converts it into a property suitable for adding to an instance. It returns a tuple containing the computed (name, property) pair.

:param cls: type. InstancePropertyHelper.
:param callable: Callable. The callable object to be converted into a property.
:param name: str. The name of the property. If not specified, it will be derived from the callable's __name__ attribute. Defaults to None.
:param reify: bool. Whether to use the reify decorator on the property. Defaults to False.
:return: Tuple. A tuple containing the computed (name, property) pair.
"""
if name is None:
    name = callable.__name__
if reify:
    return name, property(reify(callable))
else:
    return name, property(callable)

