    raise TypeError("client_addr must be a string")
if cert_principals is not None and not isinstance(cert_principals, Sequence):
    raise TypeError("cert_principals must be a sequence")
if not isinstance(ca, bool):
    raise TypeError("ca must be a boolean")

for entry in self.entries:
    if entry.match(key, client_host, client_addr, cert_principals, ca):
        return entry.options

