:return: A list of normalized search criteria.
"""
if criteria is None:
    raise ValueError("No search criteria specified.")
if isinstance(criteria, str):
    return [criteria]
if isinstance(criteria, bytes):
    return [criteria.decode(charset or "us-ascii")]
if isinstance(criteria, int):
    return [str(criteria)]
if isinstance(criteria, datetime):
    return [criteria.strftime("%Y%m%d%H%M%S")]
if isinstance(criteria, date):
    return [datetime.combine(criteria, datetime.min.time()).strftime("%Y%m%d%H%M%S")]
if isinstance(criteria, (list, tuple)):
    return [str(c) for c in criteria]
raise ValueError("Invalid search criteria.")

