for path_seq in path_seqs:
    if isinstance(path_seq, str):
        path_seq = [path_seq]
    for path in path_seq:
        path = os.path.expanduser(path)
        path = os.path.expandvars(path)
        if '*' in path or '?' in path:
            paths.extend(glob.glob(path))
        else:
            paths.append(path)
return paths

