    for i, tag in enumerate(tags.keys()[1:]):
        params['Tag.{}'.format(i + 2)] = tag
        params['Value.{}'.format(i + 2)] = tags.values()[i + 1]
if dry_run:
    params['DryRun'] = 'true'
self.connection.get_status(params)

