    elif parameter.kind == Parameter.VAR_POSITIONAL:
        if parameter.default is Parameter.empty:
            if parameter.name in args:
                free_parameters.append(parameter.name)
        else:
            if parameter.name in args:
                free_parameters.append(parameter.name)
    elif parameter.kind == Parameter.VAR_KEYWORD:
