"""This function returns a list of known IAM actions for a given prefix. It retrieves all known IAM permissions, parses the actions, and groups them by prefix. It then returns the list of actions corresponding to the given prefix.

:param prefix: String. The prefix for which known IAM actions are to be retrieved.
:return: List of String. The list of known IAM actions for the given prefix.
"""
import boto3
iam = boto3.client('iam')
response = iam.list_policies()
actions = []
for policy in response['Policies']:
    for statement in policy['PolicyVersion']['Document']['Statement']:
        if 'Action' in statement:
            for action in statement['Action']:
                if action.startswith(prefix):
                    actions.append(action)
return actions

"""This function parses a server string and extracts the host, ip, and port information from it. It first checks if the server string contains curly braces, indicating the presence of an ip address. If so, it extracts the ip address and removes it from the server string. Then, it checks if the server string contains square brackets, indicating the presence of an ipv6 hint. If so, it calls a helper function to parse the ipv6 server string. If not, it checks if the extracted ip address contains square brackets, indicating the presence of an ipv6 hint. If so, it calls the helper function to parse the ipv6 ip address. Finally, if none of the above conditions are met, it calls the helper function to parse the ipv4 server string. The function returns the host, ip, and port extracted from the server string.

:param cls: The class object.
:param server_str: String. The server string to be parsed.
:return: Tuple. The host, ip, and port extracted from the server string.
"""
if '{' in server_str:
    ip_start = server_str.find('{')
    ip_end = server_str.find('}')
    ip = server_str[ip_start + 1:ip_end]
    server_str = server_str[:ip_start] + server_str[ip_end + 1:]
elif '[' in server_str:
    return cls.parse_ipv6_server_string(server_str)
elif '[' in ip:
    return cls.parse_ipv6_ip_string(ip)
else:
    return cls.parse_ipv4_server_string(server_str)

"""This function returns a set of missing keys in the DogmaticDict instance. A key is missing if it is in the fixed set but not in the instance. These keys are added back to the instance with their corresponding values from the fixed set. If the value corresponding to a key is dogmatic, it recursively finds the missing keys in that value and adds them as '{key}.{subkey}' to the set of missing keys.

:param self: DogmaticDict. An instance of the DogmaticDict class.
:return: Set. The set of missing keys in the dictionary.
"""
missing_keys = set()
for key in self.fixed:
    if key not in self.instance:
        missing_keys.add(key)
    else:
        if isinstance(self.fixed[key], dict):
            missing_keys.update(self.revelation_dict(self.fixed[key], self.instance[key]))
        elif isinstance(self.fixed[key], list):
            missing_keys.update(self.revelation_list(self.fixed[key], self.instance[key]))
        elif isinstance(self.fixed[key], tuple):
            missing_keys.update(self.revelation_tuple(self.fixed[key], self.instance[key]))
        elif isinstance(self.fixed[key], set):
            missing_keys.update(self.revelation_set(self.fixed[key], self.instance[key]))
        elif isinstance(self.fixed[key], frozenset):
            missing_keys.update(self.revelation_frozenset(self.fixed[key], self.instance[key]))
        elif isinstance(self.fixed[key], str):
            missing_keys.update(self.revelation_str(self.fixed[key], self.instance[key]))
        elif isinstance(self.fixed[key], int):
            missing_keys.update(self.revelation_int(self.fixed[key], self.instance[key]))
        elif isinstance(self.fixed[key], float):
            missing_keys.update(self.revelation_float(self.fixed[key], self.instance[key]))
        elif isinstance(self.fixed[key], bool):
            missing_keys.update(self.revelation_bool(self.fixed[key], self.instance[key]))
        elif isinstance(self.fixed[key], type(None)):
            missing_keys.update(self.revelation_none(self.fixed[key], self.instance[key]))
        elif isinstance(self.fixed[key], DogmaticDict):
            missing_keys.update(self.revelation_dict(self.fixed[key], self.instance[key]))
        elif isinstance((self.fixed[key], DogmaticList)):
            missing_keys.update(self.revelation_list(self.fixed[key], self.instance[key]))
        elif isinstance(type(self.fixed[key]), DogmaticTuple):
            missing_keys.update(self.revelation_tuple(self.fixed[key], self.instance[key]))
        elif isinstance((self.fixed[key], DogmaticSet)):
            missing_keys.update(self.revelation_set(self.fixed[key], self.instance[key]))
        elif isinstance((self.fixed[key], DogmaticFrozenset)):
            missing_keys.update(self.revelation_frozenset(self.fixed[key], self.instance[key]))
        elif isinstance((self.fixed[key], DogmaticStr)):
            missing_keys.update(self.revelation_str(self.fixed[key], self.instance[key]))
        elif isinstance((self.fixed[key], DogmaticInt)):
            missing_keys.update(self.revelation_int(self.fixed[key], self.instance[key]))
        elif isinstance((self.fixed[key], DogmaticFloat)):
            missing_keys.update(self.revelation_float(self.fixed[key], self.instance[key]))
        elif isinstance((self.fixed[key], DogmaticBool)):
            missing_keys.update(self.revelation_bool(self.fixed[key], self.instance[key]))
        elif isinstance((self.fixed[key], DogmaticNone)):
            missing_keys.update(self.revelation_none(self.fixed[key], self.instance[key]))
        else:
            raise TypeError("The type of the value corresponding to the key '{0}' is not supported.".format(key))
return missing_keys

