"""This function adds a child tag to an XML node. It takes the name of the child tag (name), an optional text content (text), and a namespace indicator (ns). Depending on the namespace information provided, it creates a new XML element with the specified name and namespace and appends it as a child to the current node. If text content is provided, it is added as either a CDATA section or a text node to the new child element. The function then returns a new SimpleXMLElement representing the added child element along with the updated XML document and namespace information.

:param self: SimpleXMLElement. An instance of the SimpleXMLElement class.
:param name: String. The name of the child tag to be added.
:param text: String or CDATASection. The text content of the child tag. It can be a regular string or a CDATASection object.
:param ns: Bool or String. Whether to add a namespace to the child tag. If True, the namespace is added based on the instance's namespace. If False or the instance has no namespace, the child tag is added without a namespace. If a string is provided, it is used as the namespace for the child tag.
:return: SimpleXMLElement. A new SimpleXMLElement instance representing the added child tag.
"""
if ns is True:
    ns = self.ns
elif ns is False:
    ns = None
if ns is None:
    child = self.doc.createElement(name)
else:
    child = self.doc.createElementNS(ns, name)
if text is not None:
    if isinstance(text, CDATASection):
        child.appendChild(text)
    else:
        child.appendChild(self.doc.createTextNode(text))
self.doc.documentElement.appendChild(child)
return SimpleXMLElement(child, ns=ns)

"""This function takes an AST node as input and returns a list of attribute nodes that are used as assignment targets. It recursively traverses the AST and checks the type of each node to determine if it is an attribute node. If it is, the node is added to the list of assignment targets. If the node is a name, subscript, or starred node, it is skipped. If the node is a tuple or list, the function is called recursively on each element of the tuple or list and the results are concatenated. If the node type is unexpected, a warning message is printed. The format of the message is "WARNING Unexpected node type {node's type} for ast.Assign. Please report to the author github.com/gaogaotiantian/viztracer".

:param self: AstTransformer. An instance of the AstTransformer class.
:param node: ast.Node. The AST node to process.
:return: List[ast.Attribute]. A list of attribute nodes that are used as assignment targets.
"""
if isinstance(node, ast.Attribute):
    return [node]
elif isinstance(node, (ast.Name, ast.Subscript, ast.Starred)):
    return []
elif isinstance(node, (ast.Tuple, ast.List)):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.elts)))
elif isinstance(node, ast.Call):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.args)))
elif isinstance(node, ast.BinOp):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, [node.left, node.right])))
elif isinstance(node, ast.UnaryOp):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, [node])))
elif isinstance(node, ast.Compare):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, [node.ops[0], node.comparators[0]])))
elif isinstance(node, ast.BoolOp):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.values)))
elif isinstance(node, ast.IfExp):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, [node.test, node.body, node.orelse])))
elif isinstance(node, ast.Dict):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.keys)))
elif isinstance(node, ast.Set):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.elts[0])))
elif isinstance(node, ast.SetComp):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.generators)))
elif isinstance(node, ast.DictComp):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.keys + node.values)))
elif isinstance(node, ast.GeneratorExp):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.generators + node.elt)))
elif isinstance(node, ast.ListComp):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.elt + node.generators)))
elif isinstance(node, ast.Lambda):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.args.args + node.args.defaults + node.args.kw_defaults + node.args.kwarg + node.args.vararg)))
elif isinstance(node, ast.Yield):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.value)))
elif isinstance(node, ast.YieldFrom):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.value + node.elt)))
elif isinstance(node, ast.Await):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.value[0])))
elif isinstance(node, ast.Raise):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.exc + node.cause)))
elif isinstance(node, ast.Try):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.body + node.handlers + node.orelse + node.finalbody)))
elif isinstance(node, ast.TryStar):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.body)))
elif isinstance(node, ast.ExceptHandler):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.body[0].orelse + node.body[0].body + node.body[1:] + node.handlers + node.orelse + node.body)))
elif isinstance(node, ast.With):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.body[:1] + node.items + node.body[1:])))
elif isinstance(node, ast.WithItem):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.context_expr + node.optional_vars)))
elif isinstance(node, ast.Assert):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.test + node.msg)))
elif isinstance(node, ast.Global):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.names)))
elif isinstance(node, ast.Nonlocal):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.names[0])))
elif isinstance(node, ast.ClassDef):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.bases + node.keywords + node.body)))
elif isinstance(node, ast.FunctionDef):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.args + node.body + node.decorator_list)))
elif isinstance(node, ast.AsyncFunctionDef):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node + node.args + node.body + node.decorator_list)))
elif isinstance(node, ast.Return):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.value[:1] + node.value[1:])))
elif isinstance(node, ast.Delete):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.targets)))
elif isinstance(node, ast.Assign):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.targets + node.value)))
elif isinstance(node, ast.AugAssign):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.target + node.value)))
elif isinstance(node, ast.AnnAssign):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.value)) + self.get_assign_targets_with_attr(node.target))
elif isinstance(node, ast.For):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.target))) + list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.iter)))
elif isinstance(node, ast.AsyncFor):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.iter))) + list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.target)))
elif isinstance(node, ast.While):
    return list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.test))) + list(itertools.chain.from_iterable(map(self.get_assign_targets_with_attr, node.body)))
elif node is None:
    return []
else:
    warnings.warn(f"WARNING Unexpected node type {type(node)} for ast.Assign. Please report to the author github.com/gaogaotiantian/viztracer")
    return []

